// Dữ liệu mẫu
const images = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSuqLsz9o7STsDDhV5oiVeiS4SKJTX_ED1j7g&s",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQwtFKIziPu-kUh8acjWs_mtoqi9qSWz0Wdkg&s",
  "data:image/jpeg;base64,",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS1VuJXinh1EcnYsf8HqdF6cZXWHZve-_uDjA&s",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
];

const commands = [
  { id: "theme", text: "Chuyển Chế độ Tối (Dark Mode)" },
  { id: "reset", text: "Khôi phục cài đặt gốc" },
  { id: "slide", text: "Bật/Tắt Trình chiếu tự động" },
  { id: "close", text: "Đóng ứng dụng" },
];

let currentIndex = 0;
let isSlideShow = false;
let slideInterval;

const mainImage = document.getElementById("mainImage");
const cmdPalette = document.getElementById("commandPalette");
const cmdInput = document.getElementById("cmdInput");
const cmdList = document.getElementById("cmdList");

// --- 1. XỬ LÝ GALLERY ---
function updateGallery(index) {
  currentIndex = (index + images.length) % images.length;
  mainImage.src = images[currentIndex];
  document.getElementById("imgIndex").textContent =
    `Ảnh ${currentIndex + 1}/${images.length}`;
}

function toggleSlideShow() {
  isSlideShow = !isSlideShow;
  const status = document.getElementById("slideStatus");
  if (isSlideShow) {
    status.classList.remove("d-none");
    slideInterval = setInterval(() => updateGallery(currentIndex + 1), 2000);
  } else {
    status.classList.add("d-none");
    clearInterval(slideInterval);
  }
}

// --- 2. XỬ LÝ COMMAND PALETTE ---
function openPalette() {
  cmdPalette.style.display = "flex";
  cmdInput.focus();
  renderCommands("");
}

function closePalette() {
  cmdPalette.style.display = "none";
}

function renderCommands(filter) {
  cmdList.innerHTML = "";
  const filtered = commands.filter((c) =>
    c.text.toLowerCase().includes(filter.toLowerCase()),
  );

  filtered.forEach((cmd, idx) => {
    const li = document.createElement("li");
    li.className = `list-group-item ${idx === 0 ? "active" : ""}`;
    li.textContent = cmd.text;
    li.setAttribute("role", "option");
    li.setAttribute("aria-selected", idx === 0);
    cmdList.appendChild(li);
  });
}

// --- 3. LẮNG NGHE SỰ KIỆN BÀN PHÍM ---
window.addEventListener("keydown", (e) => {
  // Phím tắt mở Palette: Ctrl + K
  if (e.ctrlKey && e.key === "k") {
    e.preventDefault();
    openPalette();
    return;
  }

  // Nếu Palette đang mở
  if (cmdPalette.style.display === "flex") {
    if (e.key === "Escape") closePalette();
    if (e.key === "Enter") {
      const active = cmdList.querySelector(".active");
      if (active) alert("Đã chọn: " + active.textContent);
      closePalette();
    }
    return;
  }

  // Nếu đang ở Gallery
  if (e.key === "ArrowRight") updateGallery(currentIndex + 1);
  if (e.key === "ArrowLeft") updateGallery(currentIndex - 1);
  if (e.key >= "1" && e.key <= "9") updateGallery(parseInt(e.key) - 1);
  if (e.code === "Space") {
    e.preventDefault();
    toggleSlideShow();
  }
  if (e.key === "Escape") {
    // Thoát chế độ slide hoặc đóng gallery (nếu có popup)
    if (isSlideShow) toggleSlideShow();
  }
});

// Tìm kiếm trong Palette
cmdInput.addEventListener("input", (e) => renderCommands(e.target.value));

// Điều hướng lên xuống trong danh sách lệnh bằng phím mũi tên
cmdInput.addEventListener("keydown", (e) => {
  const items = cmdList.querySelectorAll(".list-group-item");
  let activeIdx = Array.from(items).findIndex((i) =>
    i.classList.contains("active"),
  );

  if (e.key === "ArrowDown") {
    items[activeIdx].classList.remove("active");
    activeIdx = (activeIdx + 1) % items.length;
    items[activeIdx].classList.add("active");
  } else if (e.key === "ArrowUp") {
    items[activeIdx].classList.remove("active");
    activeIdx = (activeIdx - 1 + items.length) % items.length;
    items[activeIdx].classList.add("active");
  }
});

// Khởi tạo ảnh đầu tiên
updateGallery(0);
